{
  "name": "Create Order (named vars)",
  "httpMethod": "POST",
  "pathPattern": "/orders/named",
  "targetBaseUrl": "https://jsonplaceholder.typicode.com",
  "enabled": true,
  "responses": [
    {
      "description": "Order created — orderId shared between body and SQS",
      "active": true,
      "httpStatus": 201,
      "responseHeaders": { "Content-Type": "application/json" },
      "bodyTemplate": "{\"orderId\": \"{{uuid:orderId}}\", \"status\": \"created\", \"at\": \"{{now}}\"}",
      "latencyMs": 100,
      "requestMatcher": null,
      "postActions": [
        {
          "delayMs": 2000,
          "sqsQueueUrl": "http://sqs.us-east-1.localhost.localstack.cloud:4566/000000000042/orders-events",
          "sqsMessageTemplate": "{\"event\": \"ORDER_CREATED\", \"orderId\": \"{{orderId}}\", \"at\": \"{{now}}\"}"
        }
      ]
    }
  ]
}

{
  "name": "Create Order (two UUIDs)",
  "httpMethod": "POST",
  "pathPattern": "/orders/multi-id",
  "targetBaseUrl": "https://jsonplaceholder.typicode.com",
  "enabled": true,
  "responses": [
    {
      "description": "Response with two independent named UUIDs",
      "active": true,
      "httpStatus": 201,
      "responseHeaders": { "Content-Type": "application/json" },
      "bodyTemplate": "{\"orderId\": \"{{uuid:orderId}}\", \"traceId\": \"{{uuid:traceId}}\", \"status\": \"created\"}",
      "latencyMs": 0,
      "requestMatcher": null,
      "postActions": [
        {
          "delayMs": 1000,
          "sqsQueueUrl": "http://sqs.us-east-1.localhost.localstack.cloud:4566/000000000042/orders-events",
          "sqsMessageTemplate": "{\"event\": \"ORDER_CREATED\", \"orderId\": \"{{orderId}}\", \"traceId\": \"{{traceId}}\"}"
        }
      ]
    }
  ]
}
